package com.example.billing.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Entity @Table(name="Invoices",uniqueConstraints=@UniqueConstraint(name="IX_Invoices_SubscriptionId_BillingPeriod",columnNames={"SubscriptionId","BillingPeriodStart","BillingPeriodEnd"}),indexes=@Index(name="IX_Invoices_Status",columnList="Status")) public class Invoice { @Id @Column(name="Id") public UUID id; @Column(name="CustomerId",nullable=false) public UUID customerId; @Column(name="SubscriptionId",nullable=false) public UUID subscriptionId; @Column(name="Status",length=50,nullable=false) public String status; @Column(name="AmountDue",precision=18,scale=2,nullable=false) public BigDecimal amountDue; @Column(name="AmountPaid",precision=18,scale=2,nullable=false) public BigDecimal amountPaid; @Column(name="BillingPeriodStart",nullable=false) public LocalDate billingPeriodStart; @Column(name="BillingPeriodEnd",nullable=false) public LocalDate billingPeriodEnd; @Column(name="DueDate",nullable=false) public LocalDate dueDate; @Column(name="CreatedAt",nullable=false) public OffsetDateTime createdAt; @OneToMany(mappedBy="invoice",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @OrderBy("id") public List<InvoiceLine> lines=new ArrayList<>(); }
